361: async function bootstrapCookie(req, showNo, context) {
362:   if (!showNo) return "";
363:   if (context?.cookie && /PHPSESSID=/i.test(context.cookie)) return context.cookie;
364:   let cookie = `HscomShowNo=${showNo}`;
365:   const showUrl = `${BASE_URL}/show.php?show=${encodeURIComponent(showNo)}`;
366:   try {
367:     const response = await requestText(showUrl, {
368:       method: "GET",
369:       headers: {
370:         "accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
371:         "accept-language": "en-US,en;q=0.9",
372:         "referer": `${BASE_URL}/showsel.php`,
373:         "sec-fetch-dest": "document",
374:         "sec-fetch-mode": "navigate",
375:         "sec-fetch-site": "same-origin",
376:         "upgrade-insecure-requests": "1",
377:         "user-agent": getHeader(req, "user-agent") || DEFAULT_USER_AGENT,
378:         cookie
379:       }
380:     });
381:     if (response.ok) {
382:       cookie = mergeCookies(cookie, getSetCookies(response.headers));
383:     }
384:     const scheduleResponse = await requestText(`${BASE_URL}/schedule.php`, {
385:       method: "GET",
386:       headers: {
387:         "accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
388:         "accept-language": "en-US,en;q=0.9",
389:         "referer": showUrl,
390:         "sec-fetch-dest": "document",
391:         "sec-fetch-mode": "navigate",
392:         "sec-fetch-site": "same-origin",
393:         "upgrade-insecure-requests": "1",
394:         "user-agent": getHeader(req, "user-agent") || DEFAULT_USER_AGENT,
395:         cookie
396:       }
397:     });
398:     if (scheduleResponse.ok) {
399:       cookie = mergeCookies(cookie, getSetCookies(scheduleResponse.headers));
400:     }
401:   } catch (error) {
402:     // Fall back to HscomShowNo; upstream will report the real failure if a session is required.
403:   }
404:   if (context) context.cookie = cookie;
405:   return cookie;

